const draw=()=>{if(!app)return;app.innerHTML=`<div class="sa-layout">${sidebar()}<div class="sa-main">${topbar()}<main class="sa-content">${DEMO?`<div class="sa-demo-banner"><span>ⓘ ${esc(t('preview'))}</span><span>${esc(t('learn'))}</span></div>`:''}${(pages[view]||renderOverview)()}</main></div></div>`;};
const formLead=(id)=>{const l=id?allLeads().find(x=>String(x.id)===String(id)):null;if(id&&!l)return;if(l&&!authorized(l))return;editing=l;modalSection='lead';let ls=getLists(),u=me(),can=canEdit(l),owners=getUsers().filter(x=>x.role==='seller'||x.role==='manager');if(u.role==='seller'||(!['manager','admin'].includes(u.role)))owners=owners.filter(x=>x.id===u.id);let form=`<form id="sa-lead-form"><div class="sa-modal-body"><div class="sa-form-grid">${field('company','text',l?.company,true)}${field('vat','text',l?.vat)}${field('country','select',l?.country||u.countries?.[0]||'DK',true,{options:ls.countries})}${field('office','select',l?.office||'',true,{options:ls.offices[l?.country||u.countries?.[0]||'DK']?.map(o=>[o,o])||[]})}${field('contacts','text',l?.contact,true)}${field('phone','tel',l?.phone,true)}${field('email','email',l?.email)}${field('owner','select',String(l?.owner_id||u.id),true,{options:owners.map(x=>[String(x.id),x.name])})}${field('amount','number',l?.amount_eur||'',true,{min:0,step:'0.01'})}${field('vehicles','number',l?.vehicles??'',true,{min:0,step:'1'})}${field('prob','select',String(l?.probability??30),true,{options:Array.from({length:11},(_,i)=>[String(i*10),i*10+'%'])})}${field('status','select',l?.status||'new',true,{options:Object.keys(statuses).map(s=>[s,t(statuses[s])])})}<div class="sa-form-hint full" id="sa-status-help">ⓘ ${esc(statusInfo(l?.status||'new'))}</div><div class="sa-field full"><label>${esc(t('products'))} <span class="req">*</span></label><div class="sa-checks">${ls.products.map(p=>`<label><input type="checkbox" name="products" value="${esc(p)}" ${(l?.products||[]).includes(p)?'checked':''}>${esc(p)}</label>`).join('')}</div></div>${field('date','datetime-local',l?.next_followup||'')}<div class="sa-form-hint full">ⓘ ${esc(hint('probability'))}</div>${field('reminder','select',String(l?.reminder_days??2),false,{options:[[0,'På dagen'],[1,'1 dag'],[2,'2 dage'],[3,'3 dage'],[7,'7 dage'],[14,'14 dage']].map(([k,v])=>[String(k),v])})}<div class="sa-form-hint full">ⓘ ${esc(hint('reminder'))}</div>${field('followupReason','text',l?.followup_reason)}${field('closeDate','date',l?.close_date||'')}${field('outcome','select',l?.outcome_reason||'',false,{options:[['',t('choose')],...(ls.outcomeReasons[l?.status]||[...new Set([...ls.outcomeReasons.won,...ls.outcomeReasons.lost])]).map(r=>[r,r])]})}${field('outcomeNote','text',l?.outcome_note||'')}${field('notes','textarea',l?.notes||'',false,{full:true})}${field('link','url',l?.attachment_url||'',false,{full:true})}${l?.owner_id&&Number(l.owner_id)!==Number(u.id)&&['manager','admin'].includes(u.role)?field('transferReason','text','',false,{full:true}):''}${l?`<div class="sa-section-title">${t('audit')}</div><div id="sa-audit" class="sa-field full">${DEMO?(demo.audit||[]).filter(a=>a.lead_id===l.id).slice(-12).reverse().map(a=>`<div class="sa-audit">${esc(a.when)} · ${esc(displayName(a.actor_id))} · <b>${esc(a.event)}</b></div>`).join('')||t('empty'):t('loading')}</div>`:''}</div></div><div class="sa-form-footer"><span class="sa-form-error" id="sa-form-error"></span>${btn(t('cancel'),'close-modal')}${can?`<button type="submit" class="sa-btn primary">${esc(t('save'))}</button>`:''}</div></form>`;showModal(l?t('edit')+' · '+l.company:t('create'),form);if(!can)document.querySelectorAll('#sa-lead-form input,#sa-lead-form select,#sa-lead-form textarea').forEach(x=>x.disabled=true);if(!DEMO&&l)api('audit/'+l.id).then(a=>{const el=document.getElementById('sa-audit');if(el)el.innerHTML=(a||[]).map(v=>`<div class="sa-audit">${esc(v.changed_at)} · ${esc(v.actor_name||v.actor_id)} · <b>${esc(v.event)}</b>: ${esc(v.changes||'')}</div>`).join('')||t('empty')}).catch(()=>{});};
