const api=async(path,method='GET',data)=>{const r=await fetch(CFG.rest.replace(/\/$/,'')+'/'+path.replace(/^\//,''),{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-WP-Nonce':CFG.nonce},body:data?JSON.stringify(data):undefined});let j=await r.json().catch(()=>({message:r.statusText}));if(!r.ok)throw new Error(j.message||'HTTP '+r.status);return j};
